-- Insert Challenges
INSERT INTO challenges (id, title, category, summary, problem_statement, expected_outcomes, target_sectors, reward_or_grant, author_id, is_active, created_at)
VALUES ('challenge_1', 'الفكرة 1: نظام الري الذكي بالطاقة الشمسية وحساسات التربة (AgriSmart Irrigation)', 'AgriTech & Water Efficiency', 'تطوير نظام ري مؤتمت بالكامل يعتمد على الطاقة الشمسية وحساسات رطوبة التربة وإنترنت الأشياء (IoT) للحد من هدر المياه وتقليل كلفة الطاقة على المزارعين الصغار.', 'يعاني مزارعو المناطق شبه الجافة من ارتفاع فواتير الديزل والكهرباء لتشغيل مضخات الري، بالإضافة إلى استنزاف المياه الجوفية نتيجة الري العشوائي بنسبة تزيد عن 40%، مما يؤدي إلى تلف المحاصيل أو تملح التربة.', '1. نموذج دراسة جدوى فنية ومالية لنظام ري ذكي منخفض التكلفة.
2. خطة استهداف واضحة لصغار ومتوسطي المزارعين.
3. تحليل SWOT متكامل يحدد التحديات الميدانية وفرص الدعم الحكومي.
4. نموذج أولي (MVP) يربط حساسات الرطوبة بصمامات ذكية وتطبيق هاتف.', 'الزراعة المستدامة، الطاقة المتجددة، إدارة الموارد المائية، أجهزة إنترنت الأشياء', 'منحة تمويل أولي 15,000$ + احتضان في معمل الابتكار', 'user_admin', TRUE, '2026-11-17T19:46:37.593Z')
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO challenges (id, title, category, summary, problem_statement, expected_outcomes, target_sectors, reward_or_grant, author_id, is_active, created_at)
VALUES ('challenge_2', 'الفكرة 2: شبكة غرف التبريد الشمسية وسوق المزارعين المباشر (ColdChain & FarmMarket)', 'Food Logistics & Clean Cold', 'إنشاء وحدات تبريد وتخزين للمحاصيل سريعة التلف تعمل بالطاقة النظيفة في المناطق الريفية مع منصة رقمية تربط المزارع بمحلات التجزئة والمطاعم مباشرة دون وسطاء.', 'يتلف أكثر من 35% إلى 45% من محاصيل الخضار والفواكه بعد الحصاد بسبب انعدام سلاسل التبريد القريبة من الحقول، كما يبتلع الوسطاء وسماسرة الأسواق أكثر من 60% من هامش الربح النهائي للمزارع.', '1. دراسة جدوى متكاملة لغرف تبريد متنقلة modular cold storage.
2. دراسة الجمهور المستهدف (المزارعون، تجار التجزئة، الفنادق، محلات السوبرماركت).
3. تحليل SWOT لتحويل فائض الإنتاج إلى مبيعات ذات قيمة مضافة.
4. استراتيجية تسعير واضحة تضمن نقطة تعادل مالية في أقل من 14 شهراً.', 'سلاسل الإمداد الزراعي، الأمن الغذائي، التبريد النظيف، التجارة الإلكترونية B2B', 'منحة تمويل أولي 20,000$ + دعم لوجستي وقانوني', 'user_admin', TRUE, '2026-11-17T19:46:37.842Z')
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;

