INSERT INTO submissions (id, challenge_id, user_id, author_name, title, pitch, team_name, team_members, target_audience, swot, feasibility, document_path, document_name, document_size, status, likes_count, created_at, updated_at)
VALUES ('sub_1', 'challenge_1', 'user_part1', 'سامي بوعلام (فريق SolarDrop)', 'SolarDrop: منظومة الري الذكي بالطاقة الشمسية مع الذكاء الاصطناعي الزراعي', 'نظام ذكي متكامل يعمل بالطاقة الشمسية يوفر 40% من مياه الري ويخفض فواتير الطاقة للمزارع إلى الصفر مع إشعارات مباشرة عبر الواتساب وتطبيق الهاتف.', 'فريق SolarDrop Innovation', 'سامي بوعلام (مهندس زراعي)، حمزة الشامي (مهندس إنترنت أشياء)، نادية عمار (مسؤولة مالية ودراسات جدوى)', '{"primary_segment":"صغار ومتوسطو مزارعي الخضار والفواكه والأشجار المثمرة (حيازات من 2 إلى 15 هكتار)","customer_pain_points":"ارتفاع تكاليف محروقات مضخات الديزل (أكثر من 800$ شهرياً)، صعوبة المراقبة اليدوية لرطوبة التربة ليلاً، وإجهاد المحاصيل المائي.","value_proposition":"توفير استهلاك المياه بنسبة 40%، خفض كلفة الطاقة للري إلى الصفر بالاعتماد على الطاقة الشمسية، ومراقبة الحقل بنقرة زر عبر الهاتف.","tam_sam_som":"TAM: 120,000 مزرعة على الصعيد الوطني | SAM: 35,000 مزرعة في المناطق الشمسية | SOM: 500 مزرعة في العامين الأولين.","buyer_persona":"الحاج عمر (52 عاماً)، مزارع زيتون وحمضيات، يبحث عن حل عملي وبسيط لا يتطلب مهارات برمجية معقدة ويوفر له في فاتورة الطاقة."}'::jsonb, '{"strengths":["تصميم أجهزة استشعار منخفضة التكلفة مصنعة محلياً بأجزاء قابلة للصيانة","تطبيق جوال يدعم اللغة العربية واللهجة المحلية مع تنبيهات صوتية للري","فريق تقني وزراعي متمرس يجمع بين خبرة الهاردوير والهندسة الزراعية"],"weaknesses":["الحاجة إلى رأس مال أولي لتأمين مخزون الألواح الشمسية والبطاريات","قلة الوعي التكنولوجي الأولي لدى بعض صغار المزارعين","تأخر سلاسل التوريد لبعض الرقائق الإلكترونية المستوردة"],"opportunities":["برامج الدعم الحكومي لتحويل أنظمة الري إلى الطاقة النظيفة بنسبة دعم تصل 50%","أزمة الجفاف وارتفاع وتيرة تقنين المياه تجعل الحل ضرورة حتمية وليست رفاهية","إمكانية التوسع الإقليمي إلى أسواق شمال إفريقيا والشرق الأوسط"],"threats":["دخول منتجات صينية مقلدة رخيصة الثمن ومنخفضة الجودة","تقلبات أسعار صرف العملات لشراء بطاريات الليثيوم","الظروف المناخية القاسية (عواصف رملية) تتطلب حماية إضافية للأجهزة"]}'::jsonb, '{"technical":{"summary":"نظام متكامل مكون من محطة طاقة شمسية 3.5 KW، وحدة تحكم دقيقة (Microcontroller) مع مودم LoRa/GSM، حساسات رطوبة وسعة التربة على عمقين، وصمامات لولبية هيدروليكية مؤتمتة.","readiness_level":"TRL 6: تم بناء النموذج الأولي واختباره في مزرعة تجريبية لمدة 3 أشهر بنجاح كامل.","infrastructure_needs":"ورشة تجميع واختبار، مخزن مكونات إلكترونية، وخادم سحابي لمعالجة بيانات الحساسات."},"market":{"market_demand":"طلب متسارع جداً بسبب تراجع منسوب السدود وإلزامية ترشيد مياه الري.","competitive_advantage":"خدمة ما بعد البيع الميدانية وضمان استبدال خلال 48 ساعة مع اشتراك سنوي رمزي للدعم والصيانة.","marketing_channels":"المعارض الزراعية، التعاونيات الفلاحية، قنوات يوتيوب وفيسبوك المتخصصة في الزراعة، والزيارات الميدانية المباشرة."},"financial":{"currency":"USD","capex":18500,"monthly_opex":2800,"unit_price":1450,"unit_cost":820,"break_even_months":11,"projected_year1_sales":65,"projected_year1_revenue":94250,"projected_year1_net_profit":26050,"roi_percentage":140},"operational_legal":{"legal_permits":"سجل تجاري، اعتماد سلامة التجهيزات الكهربائية، وموافقة وكالة تقنين الاتصالات لاستخدام ترددات LoRa.","team_structure":"مهندس إلكترونيات، مهندس زراعي، فني تركيب ميداني، ومسؤول مبيعات وتسويق ريفي.","implementation_phases":"المرحلة 1 (شهور 1-3): تأسيس خط التجميع الأولي وإنتاج 20 وحدة.\nالمرحلة 2 (شهور 4-7): حملة تسويقية عبر التعاونيات وتركيب 40 مزرعة.\nالمرحلة 3 (شهور 8-12): إطلاق تحديث الذكاء الاصطناعي للتنبؤ بالطقس وبدء التوسع."}}'::jsonb, '', '', 0, 'submitted', 18, '2026-11-15T19:46:38.059Z', '2026-11-17T19:46:38.059Z')
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status;
INSERT INTO submissions (id, challenge_id, user_id, author_name, title, pitch, team_name, team_members, target_audience, swot, feasibility, document_path, document_name, document_size, status, likes_count, created_at, updated_at)
VALUES ('sub_2', 'challenge_2', 'user_part2', 'مريم القادري (فريق FreshLock Box)', 'FreshLock Box: وحدات تبريد شمسية ذكية ومنصة تسويق مباشر للمحاصيل', 'حل مبتكر يضع غرف تبريد شمسية متنقلة في قلب المناطق الزراعية لإنقاذ 40% من المحاصيل الفاقدة وربط المزارع بالأسواق فورياً دون وسطاء.', 'فريق FreshLock Technologies', 'مريم القادري (رائدة أعمال)، د. يوسف العلوي (خبير تبريد وطاقات متجددة)، سهام المهدي (مديرة تطوير أعمال)', '{"primary_segment":"مزارعو الطماطم والفراولة والخضار الورقية، وشبكات المطاعم ومحلات البقالة الحديثة في المدن المجاورة","customer_pain_points":"فقدان ما بين 30% إلى 50% من المحصول خلال أيام الصيف الحارة لعدم وجود غرف تبريد قريبة، والاضطرار للبيع بأسعار بخسة للوسطاء.","value_proposition":"غرف تبريد لامركزية تعمل بالطاقة الشمسية بنظام الدفع حسب الاستخدام (Pay-per-crate) مع ربط فوري بالمشتري النهائي عبر المنصة.","tam_sam_som":"TAM: 450 مليون دولار سوق التبريد الزراعي الإقليمي | SAM: 60 مليون دولار | SOM: 2.5 مليون دولار خلال 3 سنوات.","buyer_persona":"سعيد (45 عاماً)، مزارع توت وفراولة، يخسر ثلث محصوله أسبوعياً في ذروة الموسم ويبحث عن تبريد فوري في نفس يوم الجني."}'::jsonb, '{"strengths":["حاويات تبريد معيارية (Modular) سهلة النقل والتركيب في أي بقعة زراعية دون الحاجة لشبكة كهرباء","نموذج عمل مرن: المزارع لا يشتري الغرفة بل يدفع بالصندوق المخزن (Micro-storage as a service)","تطبيق رقمي يتيح للمشترين حجز المحاصيل المبردة مسبقاً بجودة مضمونة"],"weaknesses":["تكلفة استثمارية أولية مرتفعة نسبياً لكل حاوية تبريد شمسية","الحاجة إلى صيانة دورية لنظام التبريد الفريوني في البيئات الحارة","تحدي تنظيم النقل المبرد من الحقل إلى المدينة"],"opportunities":["توجه الصناديق الخضراء والمانحين لتمويل حلول خفض الهدر الغذائي (Food Loss Reduction)","تزايد الطلب الحضري على الخضار العضوية الطازجة القادمة مباشرة من الحقل","الشراكة مع أسواق الجملة الكبرى لإنشاء نقاط تجميع معتمدة"],"threats":["مقاومة سماسرة الأسواق التقليديين الذين قد يحاولون الضغط على المزارعين لمقاطعة التخزين","ارتفاع درجات الحرارة الاستثنائية التي قد تتطلب قدرة تبريد إضافية وبطاريات أكبر","مخاطر تعطل ضواغط التبريد في أوقات ذروة الموسم"]}'::jsonb, '{"technical":{"summary":"حاويات شحن معاد تدويرها 20 قدم معزولة حرارياً بالبولي يوريثان، مزودة بنظام تبريد شمسي هجين (طاقة شمسية نهاراً + بطاريات فوسفات الليثيوم LiFePO4 ليلاً) وتحكم رقمي بالحرارة والرطوبة.","readiness_level":"TRL 5: تم إعداد التصاميم الهندسية واختيار المكونات وحساب الأحمال الحرارية بدقة.","infrastructure_needs":"موقع تثبيت مؤمن في مركز التعاونية الزراعية، ومعدات تبريد شمسية بقدرة 5 طن تبريدي."},"market":{"market_demand":"فجوة هائلة في خدمات ما بعد الحصاد؛ أكثر من 80% من المزارع الصغيرة تفتقر كلياً لأي وسيلة تبريد.","competitive_advantage":"القرب الجغرافي من الحقول بنصف ساعة مقارنة بغرف التبريد المركزية البعيدة 70 كم، وتكلفة مرنة بالصندوق.","marketing_channels":"عقود مسبقة مع التعاونيات الفلاحية، تسويق عبر تطبيق مخصص للمطاعم ومحلات الخضار الممتازة."},"financial":{"currency":"USD","capex":32000,"monthly_opex":3400,"unit_price":1.5,"unit_cost":0.45,"break_even_months":14,"projected_year1_sales":52000,"projected_year1_revenue":112000,"projected_year1_net_profit":38800,"roi_percentage":121},"operational_legal":{"legal_permits":"تراخيص السلامة الغذائية الصحية (ONSSA / Food Safety Agency)، عقد استغلال موقع مع التعاونية الزراعية.","team_structure":"مهندسة ميكانيك وتبريد، مسؤول سلاسل إمداد وتسويق، وفني صيانة كهربائية وتبريد.","implementation_phases":"المرحلة 1 (شهور 1-4): تصنيع وتشغيل أول وحدة تبريد تجريبية بسعة 15 طناً.\nالمرحلة 2 (شهور 5-8): تشغيل منصة الربط بالمطاعم وتحقيق 70% نسبة إشغال.\nالمرحلة 3 (شهور 9-15): نشر وحدتين إضافيتين وتوسيع دائرة المزارعين المشتركين."}}'::jsonb, '', '', 0, 'submitted', 24, '2026-11-16T19:46:38.270Z', '2026-11-17T19:46:38.270Z')
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status;

