INSERT INTO evaluations (id, submission_id, judge_id, judge_name, score_problem_audience, score_swot, score_feasibility_tech, score_feasibility_financial, score_innovation, total_score, feedback, strengths_observed, recommendations, created_at)
VALUES ('eval_1', 'sub_1', 'user_lajna1', 'د. كريم المنصوري (Lajna Judge)', 19, 18, 24, 23, 9, 93, 'مشروع استثنائي ودراسة جدوى مالية وفنية عالية الاحترافية. تحليل SWOT يعكس فهماً عميقاً لواقع الفلاح البسيط وتحديات الجفاف الحالية.', 'نقاط القوة: دقة حساب نقطة التعادل (11 شهراً) والاعتماد على الطاقة الشمسية المباشرة مع تكلفة تصنيع محلية منافسة.', 'التوصيات: تعزيز جانب تدريب الفلاحين وتوفير عقود دفع ميسرة بالتقسيط بالتعاون مع البنوك الزراعية.', '2026-11-17T07:46:38.480Z')
ON CONFLICT (id) DO UPDATE SET total_score = EXCLUDED.total_score;
INSERT INTO evaluations (id, submission_id, judge_id, judge_name, score_problem_audience, score_swot, score_feasibility_tech, score_feasibility_financial, score_innovation, total_score, feedback, strengths_observed, recommendations, created_at)
VALUES ('eval_2', 'sub_1', 'user_lajna2', 'م. سلمى التازي (Tech Judge)', 18, 19, 25, 22, 9, 93, 'نموذج هندسي ناضج وحل تكنولوجي مباشر لمشكلة استنزاف الفرشة المائية. استخدام LoRa فكرة ممتازة للتغلب على ضعف شبكات الهاتف في القرى.', 'نقاط القوة: الجدوى الفنية واقعية جداً وتم اختبارها في الميدان TRL 6.', 'التوصيات: تطوير غلاف واقٍ للحساسات لحمايتها من القوارض والعوامل المناخية القاسية.', '2026-11-17T09:46:38.724Z')
ON CONFLICT (id) DO UPDATE SET total_score = EXCLUDED.total_score;
INSERT INTO evaluations (id, submission_id, judge_id, judge_name, score_problem_audience, score_swot, score_feasibility_tech, score_feasibility_financial, score_innovation, total_score, feedback, strengths_observed, recommendations, created_at)
VALUES ('eval_3', 'sub_2', 'user_lajna1', 'د. كريم المنصوري (Lajna Judge)', 18, 17, 22, 23, 9, 89, 'فكرة معيارية ذكية جداً لمعالجة مشكلة الهدر الغذائي المأساوية بعد الحصاد. دراسة الجدوى المالية واعدة رغم ارتفاع كلفة الحاوية الأولى.', 'نقاط القوة: نموذج الإيراد المتنوع (الدفع حسب التخزين + عمولة البيع المباشر).', 'التوصيات: التأكد من اتفاقيات الموقع مع التعاونيات لتفادي النزاعات العقارية أو صعوبة الدخول للكهرباء الاحتياطية.', '2026-11-17T11:46:38.957Z')
ON CONFLICT (id) DO UPDATE SET total_score = EXCLUDED.total_score;
INSERT INTO evaluations (id, submission_id, judge_id, judge_name, score_problem_audience, score_swot, score_feasibility_tech, score_feasibility_financial, score_innovation, total_score, feedback, strengths_observed, recommendations, created_at)
VALUES ('eval_4', 'sub_2', 'user_lajna2', 'م. سلمى التازي (Tech Judge)', 17, 18, 23, 21, 9, 88, 'مشروع لوجستي رائد يجمع بين الأثر البيئي والجدوى الاقتصادية. التصميم المعياري يسمح بالتوسع السريع.', 'نقاط القوة: وضوح دراسة الجمهور المستهدف وتحديد الألم بدقة.', 'التوصيات: دراسة كفاءة بطاريات الليثيوم في درجات حرارة الصيف الشديدة (فوق 45 مئوية).', '2026-11-17T13:46:39.201Z')
ON CONFLICT (id) DO UPDATE SET total_score = EXCLUDED.total_score;
